from produire import produire
from format_lecon import paras,table,steps
parts=[
('Le {ronflement primaire est un bruit nocturne isolé après évaluation}. Il ne doit pas être nommé simplement parce que personne n’a observé de pause. Une maladie respiratoire du sommeil doit être recherchée selon le contexte.',paras('Le bruit résulte de vibrations des tissus des voies aériennes supérieures. Le qualificatif primaire indique que l’évaluation ne retrouve pas de syndrome respiratoire pathologique associé ; il ne s’agit pas d’un diagnostic posé sur un enregistrement sonore seul.', 'Une personne vivant seule peut avoir des apnées non observées. L’absence de témoin ne constitue donc pas un résultat négatif.')),
('Le {ronflement est fréquent mais son retentissement varie}. Il peut perturber le sommeil du partenaire et la vie sociale. Poids, âge, position et substances modifient sa survenue.',paras('Le ronflement transitoire pendant une infection nasale n’a pas la même histoire qu’un bruit quotidien ancien. Rechercher aussi une aggravation récente ou une prise de poids.', 'Aucun pourcentage de ronflement primaire en Suisse n’est avancé ici : les enquêtes sur le bruit et les études d’apnées ne mesurent pas la même population. Chez l’enfant, un ronflement persistant suit une évaluation pédiatrique distincte.')),
('La {vibration dépend de l’espace et du tonus pharyngés}. Le sommeil favorise le relâchement des tissus. La respiration buccale et une obstruction nasale peuvent accentuer le phénomène.',paras('Le voile du palais et les structures pharyngées vibrent sous l’effet du flux d’air. Une diminution partielle du calibre peut produire du bruit sans arrêt complet du débit.', 'La position dorsale peut aggraver certains ronflements. Toutefois, une réduction du son en position latérale ne prouve pas la disparition d’événements respiratoires pathologiques.')),
('Les {alarmes font reconsidérer le caractère primaire}. Pauses, étouffements et somnolence dangereuse exigent un bilan. Un bruit respiratoire avec détresse à l’éveil sort de cette définition.',paras('Cesser de conduire si des endormissements surviennent. Les professions de sécurité, une grossesse ou une maladie cardiovasculaire instable nécessitent un seuil bas d’orientation.', 'Une obstruction nasale unilatérale progressive, du sang ou une masse imposent une recherche ORL. Un simple traitement du bruit ne doit pas retarder cette démarche.')),
('L’{anamnèse précise le retentissement pour les deux personnes concernées}. Demander fréquence, position, durée et aggravants. Vérifier directement la qualité du sommeil et la vigilance du patient.',paras('L’information du partenaire est utile avec accord du patient, mais ne remplace pas son propre récit. Rechercher pauses, inspirations bruyantes de reprise, céphalées matinales, nycturie et difficultés cognitives.', 'Noter consommation d’alcool, hypnotiques, opioïdes, tabac, obstruction nasale et traitements déjà essayés. Ne pas interrompre brutalement un médicament prescrit.')),
('L’{examen cherche un obstacle ou un terrain à risque}. Évaluer poids, pression artérielle, nez, bouche et mandibule. Le bilan dentaire devient important si une orthèse est envisagée.',paras('Une anomalie anatomique visible n’est pas nécessairement la cause exclusive du bruit. Examiner amygdales, langue, palais et qualité de la respiration nasale.', 'L’examen ORL peut préciser le niveau d’obstruction. Un aspect diurne rassurant n’exclut pas une fermeture dynamique pendant le sommeil.')),
('L’{approche syndromique évite une fausse rassurance}. Le bruit isolé se distingue du bruit accompagné de symptômes respiratoires. Une maladie systémique peut modifier le tableau.',table(['Association','Décision'],[['Bruit seul, bilan rassurant.','Mesures ciblées et suivi.'],['Pauses, fatigue, étouffements ou terrain à risque.','Exploration des apnées.'],['Obstruction nasale avec prurit et éternuements.','Évaluer rhinite et éventuelle coexistence d’apnées.'],['Enfant avec agitation, énurésie ou difficultés de croissance.','Parcours pédiatrique, sans label primaire hâtif.'] ])),
('Le {diagnostic reste une conclusion clinique réévaluable}. Un questionnaire de risque ne suffit pas à lui seul. Une exploration nocturne se décide selon la suspicion.',paras('NICE recommande un bilan de SAHOS devant plusieurs signes évocateurs et rappelle que la somnolence peut manquer. Les recommandations suisses demandent un enregistrement nocturne en cas de suspicion clinique, même avec un score rassurant.', 'Il n’est pas justifié d’imposer un scanner ni une large batterie biologique à chaque ronfleur. En revanche, une incertitude importante avant une intervention nécessite l’avis du spécialiste.')),
('Les {examens sont orientés par le risque et le traitement prévu}. La polygraphie ou la polysomnographie recherche une maladie respiratoire quand elle est suspectée. Une application audio ne les remplace pas.',paras('Une oxymétrie seule peut manquer des événements ou ne pas en préciser le mécanisme. Une polygraphie négative mais discordante avec les symptômes peut conduire à une polysomnographie.', 'L’exploration ORL recherche une cause accessible à un traitement. Le bilan dentaire juge l’aptitude à supporter une orthèse, l’état parodontal et les risques articulaires.')),
('L’{algorithme commence par vérifier que le bruit est réellement isolé}. Identifier les risques, puis discuter une intervention proportionnée à la gêne. Donner des critères de réévaluation.',steps('Chercher pauses, étouffements, somnolence et facteurs de risque.', 'Orienter vers le sommeil ou l’ORL si suspicion ou anomalie.', 'Si évaluation rassurante, adapter poids, alcool, sommeil et position selon la réponse.', 'Discuter une orthèse ou une intervention spécialisée si gêne persistante.', 'Réévaluer en cas d’apparition de symptômes ou d’évolution du terrain.')),
('La {prise en charge privilégie les mesures adaptées à la cause}. Réduire l’alcool et prendre en charge un excès pondéral peuvent aider. Les dispositifs et la chirurgie nécessitent une sélection.',paras('Un essai de sommeil latéral peut être pertinent si le bruit est positionnel ; cela ne devient pas un traitement d’apnées sévères. Traiter une maladie nasale démontrée selon son indication.', 'L’orthèse avance la mandibule et nécessite une dentition et un parodonte adaptés, puis une surveillance. Une chirurgie du voile ou d’un obstacle anatomique est discutée après avis spécialisé ; résultat et effets indésirables doivent être expliqués.', 'Aucun spray ou médicament universel antironflement n’est prescrit. La source française décrit des règles de remboursement qui ne sont pas reprises pour la Suisse. La pression positive n’est pas proposée automatiquement au seul motif d’un bruit gênant.')),
('Le {suivi porte aussi sur les signes nouveaux}. Une prise de poids ou une somnolence peut modifier le diagnostic. Contrôler la tolérance d’un dispositif et l’état dentaire.',paras('Si la gêne baisse, vérifier que sommeil et vigilance restent satisfaisants. La perception du partenaire est un critère de confort, pas une mesure de l’oxygénation.', 'Après une intervention, des symptômes persistants ou nouveaux doivent conduire à une réévaluation plutôt qu’à multiplier des produits sans diagnostic. Une orthèse peut entraîner douleurs ou changements d’occlusion.')),
('Le {point clé est une rassurance conditionnée par une évaluation suffisante}. Le ronflement primaire peut être gênant sans être un syndrome d’apnées. Le diagnostic doit rester ouvert à l’évolution.',paras('Ne pas médicaliser le seul volume sonore par une prescription systématique. Ne pas banaliser non plus des pauses ou des conséquences diurnes parce que le bruit existe depuis longtemps.'))]
quiz=[('L’absence de pause observée suffit-elle ?','Non, surtout si la personne dort seule.'),('Un enregistrement sonore confirme-t-il l’absence d’apnées ?','Non.'),('Le partenaire peut-il contribuer à l’anamnèse ?','Oui, avec l’accord du patient.'),('La somnolence est-elle obligatoire dans les apnées ?','Non.'),('Une position latérale silencieuse prouve-t-elle une respiration normale ?','Non.'),('Faut-il un scanner pour tout ronfleur ?','Non.'),('Une obstruction unilatérale sanglante doit-elle être explorée ?','Oui.'),('Le ronflement persistant de l’enfant est-il automatiquement primaire ?','Non.'),('Une orthèse nécessite-t-elle une dentition adaptée ?','Oui, avec surveillance.'),('Existe-t-il ici un médicament universel contre le ronflement ?','Non.'),('La chirurgie garantit-elle la disparition du bruit ?','Non.'),('Les règles françaises de remboursement s’appliquent-elles à la Suisse ?','Non.'),('Une prise de poids peut-elle conduire à reprendre le bilan ?','Oui.'),('Quel signe change immédiatement le conseil de conduite ?','La somnolence dangereuse ou un endormissement : cesser de conduire et consulter.')]
produire(2,parts,quiz,(1,3,4,5,6,8))
